static fz_buffer *
pdf_extract_cff_subtable(fz_context *ctx, unsigned char *data, size_t size)
{
	size_t num_tables = TTF_U16(data + 4);
	size_t i;

	if (12 + num_tables * 16 > size)
		fz_throw(ctx, FZ_ERROR_GENERIC, "invalid TTF header");

