			uint64_t length = TTF_U32(record + 12);
			uint64_t end = offset + length;
			if (end > size)
				fz_throw(ctx, FZ_ERROR_GENERIC, "invalid TTF subtable offset/length");
			return fz_new_buffer_from_copied_data(ctx, data + offset, length);
		}
	}

